import{_ as e}from"./chunks/100.Bym1HttY.js";import{_ as o,o as a,c as i,ak as r}from"./chunks/framework.Ba6sv-31.js";const l="/projects/AiBlockSensor/en/latest/assets/1.DkWYu2X8.webp",n="/projects/AiBlockSensor/en/latest/assets/2.s5kWTMXj.webp",s="/projects/AiBlockSensor/en/latest/assets/3.NWV5D54d.webp",c="/projects/AiBlockSensor/en/latest/assets/4.BrSIoLbt.webp",f=JSON.parse('{"title":"16. RGB Light Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/16. RGB Light Module.md","filePath":"docs/16. RGB Light Module.md"}'),d={name:"docs/16. RGB Light Module.md"};function h(g,t,p,m,u,_){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_16-rgb-light-module" tabindex="-1">16. RGB Light Module <a class="header-anchor" href="#_16-rgb-light-module" aria-label="Permalink to &quot;16. RGB Light Module&quot;">​</a></h1><h2 id="_16-1-introduction" tabindex="-1">16.1 Introduction <a class="header-anchor" href="#_16-1-introduction" aria-label="Permalink to &quot;16.1 Introduction&quot;">​</a></h2><p>This section introduces the RGB light module, a versatile full-color LED component. Controlled through graphical programming blocks, the module creates dynamic lighting effects, including solid colors, blinking patterns, and smooth rainbow color transitions.</p><img loading="lazy" height="348" width="506" src="'+l+'" class="common_img" style="width:300px;"><h2 id="_16-2-technical-specifications" tabindex="-1">16.2 Technical Specifications <a class="header-anchor" href="#_16-2-technical-specifications" aria-label="Permalink to &quot;16.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Color channels</td><td style="text-align:center;">Red, green, blue</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 23.0 mm</td></tr></tbody></table><h2 id="_16-3-hands-on-project" tabindex="-1">16.3 Hands-On Project <a class="header-anchor" href="#_16-3-hands-on-project" aria-label="Permalink to &quot;16.3 Hands-On Project&quot;">​</a></h2><h3 id="_16-3-1-project-introduction" tabindex="-1">16.3.1 Project Introduction <a class="header-anchor" href="#_16-3-1-project-introduction" aria-label="Permalink to &quot;16.3.1 Project Introduction&quot;">​</a></h3><p>This project programs the RGB light module to cycle through red, green, blue, and yellow for 1 second each. Exploring basic color-setting blocks demonstrates how delay-based sequences create dynamic lighting patterns.</p><h3 id="_16-3-2-hardware-wiring" tabindex="-1">16.3.2 Hardware Wiring <a class="header-anchor" href="#_16-3-2-hardware-wiring" aria-label="Permalink to &quot;16.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the RGB light module to port <strong>A</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="433" width="1040" src="'+n+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among A, B, C, or D on the controller. Ensure that the port selected in the program matches the physical wiring.</strong></p></div><h3 id="_16-3-3-adding-extensions" tabindex="-1">16.3.3 Adding Extensions <a class="header-anchor" href="#_16-3-3-adding-extensions" aria-label="Permalink to &quot;16.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>RGB module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+s+'" class="common_img" style="width:800px;"><h3 id="_16-3-4-complete-program-and-analysis" tabindex="-1">16.3.4 Complete Program and Analysis <a class="header-anchor" href="#_16-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;16.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>In the main program, continuously execute the color-switching sequence for the RGB light module on port A using a loop.</p><ul><li><p>Set the RGB light to red and wait 1 second.</p></li><li><p>Set the RGB light to green and wait 1 second.</p></li><li><p>Set the RGB light to blue and wait 1 second.</p></li><li><p>Set the RGB light to yellow and wait 1 second, then repeat the entire lighting cycle.</p></li></ul></li></ol><img loading="lazy" height="563" width="490" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1fLfLXEVjSMZdojOq7C44xJqZIBm4MDem?usp=sharing" target="_blank" rel="noreferrer">Program Files/ 16 RGB Light Module.sb3</a>.</strong></p></div><h3 id="_16-3-5-program-upload" tabindex="-1">16.3.5 Program Upload <a class="header-anchor" href="#_16-3-5-program-upload" aria-label="Permalink to &quot;16.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_16-3-6-program-outcome" tabindex="-1">16.3.6 Program Outcome <a class="header-anchor" href="#_16-3-6-program-outcome" aria-label="Permalink to &quot;16.3.6 Program Outcome&quot;">​</a></h3><p>After uploading the program, the RGB light module automatically cycles through vivid colors. It lights up in red, green, blue, and yellow sequentially for 1 second each before repeating the cycle, showcasing dynamic multi-color output.</p>',25)])])}const x=o(d,[["render",h]]);export{f as __pageData,x as default};
